private static boolean isSteppingNumber(int num) {
    int currDigit = num % 10;
    int prevDigit = -1;
    while (num > 0) {
        int digit = num % 10;
        if (digit - prevDigit != 1 && prevDigit - digit != 1) {
            return false;
        }
        prevDigit = currDigit;
        currDigit = digit;
        num /= 10;
    }
    return true;
}

