      dp[i][j] = Math.min(dp[i - 1][j], dp[i][j - 1]);
      if (i == 1 || j == 1) dp[i][j] = 1;

      if (mat[i - 1][j - 1] == 1) {
        dp[i][j] = Math.max(dp[i][j], dp[i - 1][j - 1] + 1);
        max = Math.max(dp[i][j], max);
      }
    }
  }

  return max;
}

