public static boolean isBoomerang(int[][] points) {
    // Check if the input array contains exactly 3 points
    if (points.length != 3) {
        return false;
    }
    // Check if the three points are collinear
    double a = points[1][0] - points[0][0];
    double b = points[1][1] - points[0][1];
    double c = points[2][0] - points[0][0];
    double d = points[2][1] - points[0][1];
    if (a * d == b * c) {
        return false;
    }
    // Check if the three points are not aligned vertically
    if (a == 0 || b == 0 || c == 0 || d == 0) {
        return false;
    }
    // Check if the segments formed by the points have the same slope
    if (a * d != b * c) {
        return false;
    }
    // Check if the three points are not aligned horizontally
    if (a == 0 || b == 0 || c == 0 || d == 0) {
        return false;
    }
    // Check if the segments formed by the points have the same slope
    if (a * d == b * c) {
        return false;
    }
    // If all checks pass, the points form a boomerang
    return true;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) return -1;
    int[] uglyNumbers = new int[n+1];
    uglyNumbers[0] = 1;
    int index2 = 0;
    int index3 = 0;
    int index5 = 0;
    int nextUglyNumber;
    for (int i = 1; i < n; i++) {
        nextUglyNumber = Math.min(2 * uglyNumbers[index2], Math.min(3 * uglyNumbers[index3], 5 * uglyNumbers[index5]));
        uglyNumbers[i] = nextUglyNumber;
        if (nextUglyNumber == 2 * uglyNumbers[index2]) index2++;
        if (nextUglyNumber == 3 * uglyNumbers[index3]) index3++;
        if (nextUglyNumber == 5 * uglyNumbers[index5]) index5++;
    }
    return uglyNumbers[n-1];
}

